SUPPORTED_LANGUAGES = ("fr", "en", "vi")


def t(language: str, key: str, **kwargs: object) -> str:
    """Translate a UI string, failing loudly rather than mixing languages."""
    if language not in SUPPORTED_LANGUAGES:
        raise ValueError("Unsupported language")
    value = TEXT[language][key]
    if not isinstance(value, str):
        raise TypeError("Requested translation is not a string")
    return value.format(**kwargs)


def category_label(language: str, category: str) -> str:
    return TEXT[language]["life_categories"][category]


def canonical_category(value: str) -> str:
    """Preserve imported legacy files with English display labels as categories."""
    aliases = {
        "Child / Dependent": "child", "Health / Care": "health", "Large purchase": "purchase",
        "Unemployment": "unemployment", "Education": "education", "Relocation": "relocation", "Other": "other",
    }
    if value in TEXT["fr"]["life_categories"]:
        return value
    return aliases.get(value, "other")